  const lines = [];
  for (let index = 0; index < node.items.length; index += 1) {
    const item = node.items[index];
    const prefix = spaces(indent) + '- ';
    if (isInlineNode(item)) {
      lines.push(prefix + dumpInline(item));
      continue;
    }
    const childLines = renderCollectionChild(item, indent + 2);
    lines.push(prefix + childLines[0].slice(indent + 2));
    for (let childIndex = 1; childIndex < childLines.length; childIndex += 1) {
      lines.push(childLines[childIndex]);
    }
  }
  return lines;
