function baseName(path) {
  if (!path || path.length === 0) {
    return 'test13.mjs';
  }
  let lastSlash = -1;
  for (let index = 0; index < path.length; index += 1) {
    const char = path[index];
    if (char === '/' || char === '\\') {
      lastSlash = index;
    }
  }
  return path.slice(lastSlash + 1);
}

function usage(programName) {
  return 'usage: ' + programName + ' [-h] --a A\n';
}

function help(programName) {
  return (
    usage(programName) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n'
  );
}

export function parseCommandLine(argv) {
  const programName = baseName(argv[1]);
  const args = argv.slice(2);

  let hasA = false;
  let valueA = '';
  let expectingA = false;
  const extras = [];

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index];

    if (expectingA) {
      if (token.length > 1 && token[0] === '-') {
        return {
          exitCode: 2,
          stdout: '',
          stderr:
            usage(programName) +
            programName +
            ': error: argument --a: expected one argument\n',
        };
      }
      valueA = token;
      hasA = true;
      expectingA = false;
      continue;
    }

    if (token === '-h' || token === '--help') {
      return {
        exitCode: 0,
        stdout: help(programName),
        stderr: '',
      };
    }

    if (token === '--') {
      for (let scan = index + 1; scan < args.length; scan += 1) {
        extras.push(args[scan]);
      }
      break;
    }

    if (token === '--a') {
      expectingA = true;
      continue;
    }

    if (token.length >= 4 && token.slice(0, 4) === '--a=') {
      valueA = token.slice(4);
      hasA = true;
      continue;
    }

    extras.push(token);
  }

  if (expectingA) {
    return {
      exitCode: 2,
      stdout: '',
      stderr:
        usage(programName) +
        programName +
        ': error: argument --a: expected one argument\n',
    };
  }

  if (!hasA) {
    return {
      exitCode: 2,
      stdout: '',
      stderr:
        usage(programName) +
        programName +
        ': error: the following arguments are required: --a\n',
    };
  }

  if (extras.length > 0) {
    return {
      exitCode: 2,
      stdout: '',
      stderr:
        usage(programName) +
        programName +
        ': error: unrecognized arguments: ' +
        extras.join(' ') +
        '\n',
    };
  }

  return {
    exitCode: null,
    stdout: '',
    stderr: '',
    valueA,
  };
}

