    const char = path[index];
    if (char === '/' || char === '\\') {
      lastSlash = index;
    }
  }
  return path.slice(lastSlash + 1);
}

function usage(programName) {
  return 'usage: ' + programName + ' [-h] --a A\n';
}

function help(programName) {
  return (
    usage(programName) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n'
  );
}

function errorText(programName, message) {
  return usage(programName) + programName + ': error: ' + message + '\n';
}

export function parseCommandLine(argv) {
  const programName = baseName(argv[1]);
  const args = argv.slice(2);

  let hasA = false;
