    }

    if (token === '--a') {
      expectingA = true;
      continue;
    }

    if (token.length >= 4 && token.slice(0, 4) === '--a=') {
      valueA = token.slice(4);
      hasA = true;
      continue;
    }

    extras.push(token);
  }

  if (expectingA) {
    return {
      exitCode: 2,
      stdout: '',
      stderr: errorText(programName, 'argument --a: expected one argument'),
    };
  }

  if (!hasA) {
    return {
      exitCode: 2,
      stdout: '',
      stderr: errorText(programName, 'the following arguments are required: --a'),
    };
  }

  if (extras.length > 0) {
